INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('11e04c0f-c10f-58c8-a012-a3526b5dea2c','فضل الذكر في القرآن: معنى التذكر والشكر','فضل الذكر في القرآن: معنى التذكر والشكر','Dhikr and Quran Educational Article','dhikr-virtue-quran-meaning','يظهر الذكر في القرآن بوصفه صلة واعية بالله، لا مجرد ترديد سريع منفصل عن السلوك. تربط الآية 2:152 بين ذكر الله وشكره، ولذلك يمكن للقارئ أن يسأل نفسه بعد الذكر: هل ازداد وعيه بالنعم؟ وهل انعكس ذلك على كلامه وقراراته؟ وتوجه آيات الأحزاب إلى كثرة الذكر والتسبيح صباحًا ومساءً، فيفهم المسلم أن الاستمرار أهم من الحماس المؤقت. هذا المقال شرح تعليمي عام، ولا يضيف عددًا أو وقتًا أو فضيلة خاصة خارج النصوص المشار إليها. المراجع: https://quran.com/2/152 و https://quran.com/33/41-42.','يظهر الذكر في القرآن بوصفه صلة واعية بالله، لا مجرد ترديد سريع منفصل عن السلوك. تربط الآية 2:152 بين ذكر الله وشكره، ولذلك يمكن للقارئ أن يسأل نفسه بعد الذكر: هل ازداد وعيه بالنعم؟ وهل انعكس ذلك على كلامه وقراراته؟ وتوجه آيات الأحزاب إلى كثرة الذكر والتسبيح صباحًا ومساءً، فيفهم المسلم أن الاستمرار أهم من الحماس المؤقت. هذا المقال شرح تعليمي عام، ولا يضيف عددًا أو وقتًا أو فضيلة خاصة خارج النصوص المشار إليها. المراجع: https://quran.com/2/152 و https://quran.com/33/41-42.',NULL,'شرح تعليمي لمعنى الذكر في القرآن وصلته بالشكر والاستمرار، مع إحالات مباشرة للآيات.','شرح تعليمي لمعنى الذكر في القرآن وصلته بالشكر والاستمرار، مع إحالات مباشرة للآيات.',NULL,'فريق تحرير ذِكر',ARRAY['الأذكار','القرآن','الشكر'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/2/152", "https://quran.com/33/41-42"], "source_note": "Original educational explanation; primary sources are linked for verification."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('749533f6-dac7-588b-96b8-04c48851fca9','ذكر الله وطمأنينة القلب: قراءة مسؤولة للآية','ذكر الله وطمأنينة القلب: قراءة مسؤولة للآية','Dhikr and Quran Educational Article','dhikr-quiet-heart-not-cure','تذكر سورة الرعد أن القلوب تطمئن بذكر الله. تعطي الآية معنى إيمانيًا عميقًا، لكنها لا تسمح للمنصة بأن تشخّص القلق أو تعد بزوال مرض نفسي أو جسدي بمجرد قراءة نص. يمكن للمسلم أن يجعل الذكر جزءًا من عبادته وتهدئة يومه، مع طلب المساعدة الطبية والنفسية عند استمرار الأعراض أو وجود خطر. ومن المفيد تسجيل ما يساعد على حضور القلب، مثل تقليل المشتتات وفهم المعنى، دون تحويل التجربة الشخصية إلى حكم شرعي عام. المراجع: https://quran.com/13/28 و https://quran.com/2/286.','تذكر سورة الرعد أن القلوب تطمئن بذكر الله. تعطي الآية معنى إيمانيًا عميقًا، لكنها لا تسمح للمنصة بأن تشخّص القلق أو تعد بزوال مرض نفسي أو جسدي بمجرد قراءة نص. يمكن للمسلم أن يجعل الذكر جزءًا من عبادته وتهدئة يومه، مع طلب المساعدة الطبية والنفسية عند استمرار الأعراض أو وجود خطر. ومن المفيد تسجيل ما يساعد على حضور القلب، مثل تقليل المشتتات وفهم المعنى، دون تحويل التجربة الشخصية إلى حكم شرعي عام. المراجع: https://quran.com/13/28 و https://quran.com/2/286.',NULL,'تفسير تربوي غير علاجي لآية طمأنينة القلب، مع احترام حدود المحتوى الديني والصحي.','تفسير تربوي غير علاجي لآية طمأنينة القلب، مع احترام حدود المحتوى الديني والصحي.',NULL,'فريق تحرير ذِكر',ARRAY['الأذكار','الطمأنينة','الصحة النفسية'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/13/28", "https://quran.com/2/286"], "source_note": "Original educational explanation; primary sources are linked for verification."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('dacbbcb1-b11b-535f-8846-59e9966ac59b','الصلاة وذكر الله: كيف يحافظ الطالب على حضور المعنى؟','الصلاة وذكر الله: كيف يحافظ الطالب على حضور المعنى؟','Dhikr and Quran Educational Article','dhikr-and-prayer-remembrance','تربط سورة طه إقامة الصلاة بذكر الله، وهذا يفتح بابًا عمليًا للطالب والموظف: لا تكون الصلاة مجرد مهمة زمنية، بل لحظة يعود فيها إلى المعنى والنية. يساعد على ذلك فهم ما يقرأه، والاستعداد قبل الأذان، وإبعاد الهاتف، ثم العودة إلى العمل بهدوء بعد الصلاة. لا يقدم المقال حكمًا فقهيًا في مسائل الأعذار أو الجمع أو القضاء؛ فهذه مسائل تتغير بتغير الحال ويُسأل فيها أهل العلم. المقصود هو بناء عادة حضور وتوازن، لا تقييم الناس أو ادعاء أن طريقة واحدة تناسب الجميع. المرجع: https://quran.com/20/14.','تربط سورة طه إقامة الصلاة بذكر الله، وهذا يفتح بابًا عمليًا للطالب والموظف: لا تكون الصلاة مجرد مهمة زمنية، بل لحظة يعود فيها إلى المعنى والنية. يساعد على ذلك فهم ما يقرأه، والاستعداد قبل الأذان، وإبعاد الهاتف، ثم العودة إلى العمل بهدوء بعد الصلاة. لا يقدم المقال حكمًا فقهيًا في مسائل الأعذار أو الجمع أو القضاء؛ فهذه مسائل تتغير بتغير الحال ويُسأل فيها أهل العلم. المقصود هو بناء عادة حضور وتوازن، لا تقييم الناس أو ادعاء أن طريقة واحدة تناسب الجميع. المرجع: https://quran.com/20/14.',NULL,'تطبيقات يومية لربط الصلاة بذكر الله دون تحويل المقال إلى فتوى شخصية.','تطبيقات يومية لربط الصلاة بذكر الله دون تحويل المقال إلى فتوى شخصية.',NULL,'فريق تحرير ذِكر',ARRAY['الأذكار','الصلاة','الطلاب'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/20/14"], "source_note": "Original educational explanation; primary sources are linked for verification."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('51b60ac7-62ce-551b-a511-c02fcdb288dd','أذكار الصباح والمساء: تنظيم القراءة وحفظ المصدر','أذكار الصباح والمساء: تنظيم القراءة وحفظ المصدر','Dhikr and Quran Educational Article','morning-evening-adhkar-source','تذكر آيات الأحزاب التسبيح بكرة وأصيلًا، وتضم مصادر الأذكار الحديثية أبوابًا للصباح والمساء. لذلك ينبغي أن يعرض التطبيق نص الذكر، ومرجعه، والوقت أو العدد إذا كان مثبتًا في المصدر نفسه، وألا يضيف عبارة مثل "مضمون الإجابة" أو "حماية مؤكدة" دون دليل. يستطيع المستخدم إنشاء قائمة شخصية من مواد موثقة، ثم يراجعها بدل نسخ صور مجهولة من الشبكات الاجتماعية. صفحة Hisn al-Muslim في Sunnah.com تعرض مراجع مرقمة للأذكار، وتبقى الإحالة إلى الصفحة الأصلية أفضل من إعادة نشر نص بلا تخريج. المراجع: https://quran.com/33/41-42 و https://sunnah.com/hisn و https://sunnah.com/hisn:92.','تذكر آيات الأحزاب التسبيح بكرة وأصيلًا، وتضم مصادر الأذكار الحديثية أبوابًا للصباح والمساء. لذلك ينبغي أن يعرض التطبيق نص الذكر، ومرجعه، والوقت أو العدد إذا كان مثبتًا في المصدر نفسه، وألا يضيف عبارة مثل "مضمون الإجابة" أو "حماية مؤكدة" دون دليل. يستطيع المستخدم إنشاء قائمة شخصية من مواد موثقة، ثم يراجعها بدل نسخ صور مجهولة من الشبكات الاجتماعية. صفحة Hisn al-Muslim في Sunnah.com تعرض مراجع مرقمة للأذكار، وتبقى الإحالة إلى الصفحة الأصلية أفضل من إعادة نشر نص بلا تخريج. المراجع: https://quran.com/33/41-42 و https://sunnah.com/hisn و https://sunnah.com/hisn:92.',NULL,'منهج عملي لعرض أذكار الصباح والمساء مع النص والمرجع والعدد المثبت فقط.','منهج عملي لعرض أذكار الصباح والمساء مع النص والمرجع والعدد المثبت فقط.',NULL,'فريق تحرير ذِكر',ARRAY['أذكار الصباح','أذكار المساء','التوثيق'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/33/41-42", "https://sunnah.com/hisn", "https://sunnah.com/hisn:92"], "source_note": "Original educational explanation; primary sources are linked for verification."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('b0aa86cf-5546-5709-a1e1-4d1cb8985f86','الذكر والشكر: تحويل المعنى إلى سلوك يومي','الذكر والشكر: تحويل المعنى إلى سلوك يومي','Dhikr and Quran Educational Article','dhikr-gratitude-practical-life','تجمع الآية 2:152 بين ذكر الله وشكره، فيستفيد القارئ من الجمع بين اللسان والعمل. بعد الذكر يمكن أن يختار فعلًا صغيرًا يناسب النعمة: رد حق، شكر والدين، مساعدة محتاج، أو ترك أذى. لا يعني ذلك أن كل تجربة دنيوية ستتغير فورًا، ولا أن الشكر يلغي الحزن أو المسؤولية. المقصود أن يصبح الذكر سببًا لمراجعة السلوك، وأن تُقاس الاستفادة بصدق العمل لا بعدد المنشورات أو التسجيلات. المراجع: https://quran.com/2/152 و https://quran.com/14/7.','تجمع الآية 2:152 بين ذكر الله وشكره، فيستفيد القارئ من الجمع بين اللسان والعمل. بعد الذكر يمكن أن يختار فعلًا صغيرًا يناسب النعمة: رد حق، شكر والدين، مساعدة محتاج، أو ترك أذى. لا يعني ذلك أن كل تجربة دنيوية ستتغير فورًا، ولا أن الشكر يلغي الحزن أو المسؤولية. المقصود أن يصبح الذكر سببًا لمراجعة السلوك، وأن تُقاس الاستفادة بصدق العمل لا بعدد المنشورات أو التسجيلات. المراجع: https://quran.com/2/152 و https://quran.com/14/7.',NULL,'مقال تربوي عن صلة الذكر بالشكر والعمل الصالح دون وعود دنيوية غير موثقة.','مقال تربوي عن صلة الذكر بالشكر والعمل الصالح دون وعود دنيوية غير موثقة.',NULL,'فريق تحرير ذِكر',ARRAY['الأذكار','الشكر','الأخلاق'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/2/152", "https://quran.com/14/7"], "source_note": "Original educational explanation; primary sources are linked for verification."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('f4f2bd14-f6fa-5087-b716-6313343c87bb','قراءة آيات الذكر بتدبر لا بسرعة فقط','قراءة آيات الذكر بتدبر لا بسرعة فقط','Dhikr and Quran Educational Article','quran-verses-dhikr-reflection','تعرض آيات القرآن موضوع الذكر في سياقات متعددة، ولذلك لا يكفي جمع الآيات في قائمة ثم قراءتها بلا فهم للسياق. يبدأ التدبر بقراءة الآية في موضعها، ومعرفة السورة، والرجوع إلى تفسير موثوق عند الحاجة، ثم كتابة معنى عملي لا ينسب إلى الآية أكثر مما تحتمل. يمكن للقارئ أن يقارن بين الأمر بالذكر، وذكر الشكر، وذكر الصباح والمساء، مع ترك التفاصيل التي لم يثبتها المصدر. هذه الطريقة تمنع تحويل الآيات إلى عبارات تسويقية وتساعد الطالب على إعداد بحث واضح المراجع. المراجع: https://quran.com/2/152 و https://quran.com/33/41-42 و https://quran.com/7/205.','تعرض آيات القرآن موضوع الذكر في سياقات متعددة، ولذلك لا يكفي جمع الآيات في قائمة ثم قراءتها بلا فهم للسياق. يبدأ التدبر بقراءة الآية في موضعها، ومعرفة السورة، والرجوع إلى تفسير موثوق عند الحاجة، ثم كتابة معنى عملي لا ينسب إلى الآية أكثر مما تحتمل. يمكن للقارئ أن يقارن بين الأمر بالذكر، وذكر الشكر، وذكر الصباح والمساء، مع ترك التفاصيل التي لم يثبتها المصدر. هذه الطريقة تمنع تحويل الآيات إلى عبارات تسويقية وتساعد الطالب على إعداد بحث واضح المراجع. المراجع: https://quran.com/2/152 و https://quran.com/33/41-42 و https://quran.com/7/205.',NULL,'خطوات تدبر وبحث في آيات الذكر مع الحفاظ على السياق وعدم تحميل الآية ما لا تثبته.','خطوات تدبر وبحث في آيات الذكر مع الحفاظ على السياق وعدم تحميل الآية ما لا تثبته.',NULL,'فريق تحرير ذِكر',ARRAY['القرآن','التدبر','البحث المدرسي'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/2/152", "https://quran.com/33/41-42", "https://quran.com/7/205"], "source_note": "Original educational explanation; primary sources are linked for verification."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('322f44b0-e64b-5867-bcfb-f63d614203fa','الذكر أثناء العمل والسعي: عبادة لا تعني ترك المسؤولية','الذكر أثناء العمل والسعي: عبادة لا تعني ترك المسؤولية','Dhikr and Quran Educational Article','dhikr-work-and-responsibility','تذكر سورة الجمعة أنه بعد قضاء الصلاة ينتشر الناس في الأرض ويبتغون من فضل الله، مع الأمر بذكر الله كثيرًا. يفيد هذا السياق في تصحيح تصور شائع: الذكر لا يعني الانسحاب من الدراسة والعمل، كما أن الانشغال لا يبرر الغفلة الدائمة. يمكن تنظيم فواصل قصيرة للذكر دون تعطيل حقوق العملاء أو الزملاء، وحفظ الأمانة في الوقت والمال والبيانات. لا يحدد المقال حكمًا تفصيليًا لكل مهنة أو عقد، لكنه يوضح أن العبادة والأسباب والمسؤولية يمكن أن تجتمع. المراجع: https://quran.com/62/10 و https://quran.com/4/58.','تذكر سورة الجمعة أنه بعد قضاء الصلاة ينتشر الناس في الأرض ويبتغون من فضل الله، مع الأمر بذكر الله كثيرًا. يفيد هذا السياق في تصحيح تصور شائع: الذكر لا يعني الانسحاب من الدراسة والعمل، كما أن الانشغال لا يبرر الغفلة الدائمة. يمكن تنظيم فواصل قصيرة للذكر دون تعطيل حقوق العملاء أو الزملاء، وحفظ الأمانة في الوقت والمال والبيانات. لا يحدد المقال حكمًا تفصيليًا لكل مهنة أو عقد، لكنه يوضح أن العبادة والأسباب والمسؤولية يمكن أن تجتمع. المراجع: https://quran.com/62/10 و https://quran.com/4/58.',NULL,'شرح توازن الذكر مع العمل والمسؤولية المهنية مستندًا إلى سياق سورة الجمعة.','شرح توازن الذكر مع العمل والمسؤولية المهنية مستندًا إلى سياق سورة الجمعة.',NULL,'فريق تحرير ذِكر',ARRAY['الأذكار','العمل','الأمانة'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://quran.com/62/10", "https://quran.com/4/58"], "source_note": "Original educational explanation; primary sources are linked for verification."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
INSERT INTO public.articles (id,title,title_ar,title_en,slug,content,content_ar,content_en,summary,summary_ar,summary_en,author,tags,featured,published,views,metadata) VALUES ('35603dfb-4be2-597e-b45f-40e3e44740be','كيف نتحقق من فضائل الأذكار قبل نشرها؟','كيف نتحقق من فضائل الأذكار قبل نشرها؟','Dhikr and Quran Educational Article','verify-dhikr-virtues','تنتشر في الرسائل عبارات تنسب إلى ذكر معين عددًا محددًا أو ثوابًا ضخمًا أو أثرًا مضمونًا. المنهج الآمن هو البحث عن النص في مصدر حديثي معروف، تسجيل الكتاب أو الباب أو رقم المرجع، ثم التفريق بين نص الذكر وشرح العلماء والتجربة الشخصية. إذا لم نجد مصدرًا واضحًا، ننشره بوصفه دعاءً عامًا إن كان معناه سليمًا، ولا ننسب إليه سنة أو فضيلة خاصة. كما لا يجوز للمنصة أن تستبدل المصدر بنص مولد آليًا؛ فالذكاء الاصطناعي قد يساعد في الفهرسة لكنه ليس مرجعًا دينيًا. المراجع: https://sunnah.com/hisn و https://sunnah.com/developers و https://quran.com/49/6.','تنتشر في الرسائل عبارات تنسب إلى ذكر معين عددًا محددًا أو ثوابًا ضخمًا أو أثرًا مضمونًا. المنهج الآمن هو البحث عن النص في مصدر حديثي معروف، تسجيل الكتاب أو الباب أو رقم المرجع، ثم التفريق بين نص الذكر وشرح العلماء والتجربة الشخصية. إذا لم نجد مصدرًا واضحًا، ننشره بوصفه دعاءً عامًا إن كان معناه سليمًا، ولا ننسب إليه سنة أو فضيلة خاصة. كما لا يجوز للمنصة أن تستبدل المصدر بنص مولد آليًا؛ فالذكاء الاصطناعي قد يساعد في الفهرسة لكنه ليس مرجعًا دينيًا. المراجع: https://sunnah.com/hisn و https://sunnah.com/developers و https://quran.com/49/6.',NULL,'سياسة تحقق عملية تمنع نشر فضائل مجهولة أو نسبتها إلى السنة دون مرجع محدد.','سياسة تحقق عملية تمنع نشر فضائل مجهولة أو نسبتها إلى السنة دون مرجع محدد.',NULL,'فريق تحرير ذِكر',ARRAY['الأذكار','الحديث','التحقق الرقمي'],false,true,0,'{"editorial": true, "not_hadith_quote": true, "not_fatwa": true, "source_urls": ["https://sunnah.com/hisn", "https://sunnah.com/developers", "https://quran.com/49/6"], "source_note": "Original educational explanation; primary sources are linked for verification."}'::jsonb) ON CONFLICT (slug) DO UPDATE SET title=excluded.title,title_ar=excluded.title_ar,title_en=excluded.title_en,content=excluded.content,content_ar=excluded.content_ar,content_en=excluded.content_en,summary=excluded.summary,summary_ar=excluded.summary_ar,summary_en=excluded.summary_en,author=excluded.author,tags=excluded.tags,published=true,metadata=excluded.metadata,updated_at=now();
